window.__code__["middleware-longterm-memory-reme-middleware-py-85"] = {"code_id": "middleware-longterm-memory-reme-middleware-py-85", "kind": "src", "title": "_middleware.py:85", "source_path": "agentscope/src/agentscope/middleware/_longterm_memory/_reme/_middleware.py", "highlight_line": 85, "code_html": "<div class=\"code-body\">\n<div class=\"c-line\" data-line=\"1\"><span class=\"c-no\">1</span><span class=\"c-src\"><span class=\"c-com\"># -*- coding: utf-8 -*-</span></span></div>\n<div class=\"c-line\" data-line=\"2\"><span class=\"c-no\">2</span><span class=\"c-src\"><span class=\"c-str\">&quot;&quot;</span>&quot;ReMe-backed long-term memory middleware <span class=\"c-kw\">for</span> AgentScope agents.</span></div>\n<div class=\"c-line\" data-line=\"3\"><span class=\"c-no\">3</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"4\"><span class=\"c-no\">4</span><span class=\"c-src\">`ReMe &lt;https://github.com/agentscope-ai/ReMe&gt;`_ <span class=\"c-kw\">is</span> a file-based memory</span></div>\n<div class=\"c-line\" data-line=\"5\"><span class=\"c-no\">5</span><span class=\"c-src\">toolkit built on AgentScope. This middleware **embeds the ReMe</span></div>\n<div class=\"c-line\" data-line=\"6\"><span class=\"c-no\">6</span><span class=\"c-src\">application <span class=\"c-kw\">in</span>-process** (no separate service to run); a chat model <span class=\"c-kw\">for</span></span></div>\n<div class=\"c-line\" data-line=\"7\"><span class=\"c-no\">7</span><span class=\"c-src\">ReMe&<span class=\"c-com\">#x27;s LLM-backed jobs is configured once at construction.</span></span></div>\n<div class=\"c-line\" data-line=\"8\"><span class=\"c-no\">8</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"9\"><span class=\"c-no\">9</span><span class=\"c-src\">ReMe records memory by **listening to the conversation through the</span></div>\n<div class=\"c-line\" data-line=\"10\"><span class=\"c-no\">10</span><span class=\"c-src\">``on_reply`` hook** — after every reply the new exchange <span class=\"c-kw\">is</span> written back</span></div>\n<div class=\"c-line\" data-line=\"11\"><span class=\"c-no\">11</span><span class=\"c-src\">via ReMe&<span class=\"c-com\">#x27;s ``auto_memory`` job, in *all* modes. The agent never writes</span></span></div>\n<div class=\"c-line\" data-line=\"12\"><span class=\"c-no\">12</span><span class=\"c-src\">memory itself; there <span class=\"c-kw\">is</span> no manual add tool. The ``mode`` parameter only</span></div>\n<div class=\"c-line\" data-line=\"13\"><span class=\"c-no\">13</span><span class=\"c-src\">controls **retrieval**:</span></div>\n<div class=\"c-line\" data-line=\"14\"><span class=\"c-no\">14</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"15\"><span class=\"c-no\">15</span><span class=\"c-src\">- ``<span class=\"c-str\">&quot;static_control&quot;</span>`` — search ReMe when a reply starts <span class=\"c-kw\">and</span> inject the</span></div>\n<div class=\"c-line\" data-line=\"16\"><span class=\"c-no\">16</span><span class=\"c-src\">  retrieved memories into context before a later reasoning step (plus the</span></div>\n<div class=\"c-line\" data-line=\"17\"><span class=\"c-no\">17</span><span class=\"c-src\">  automatic write-back). Retrieval runs concurrently <span class=\"c-kw\">with</span> the reply, so</span></div>\n<div class=\"c-line\" data-line=\"18\"><span class=\"c-no\">18</span><span class=\"c-src\">  injection <span class=\"c-kw\">is</span> best-effort: a single-shot reply may finish first.</span></div>\n<div class=\"c-line\" data-line=\"19\"><span class=\"c-no\">19</span><span class=\"c-src\">- ``<span class=\"c-str\">&quot;agent_control&quot;</span>`` — expose a ``memory_search`` tool the agent calls</span></div>\n<div class=\"c-line\" data-line=\"20\"><span class=\"c-no\">20</span><span class=\"c-src\">  on demand (plus the automatic write-back); no auto-retrieval.</span></div>\n<div class=\"c-line\" data-line=\"21\"><span class=\"c-no\">21</span><span class=\"c-src\">- ``<span class=\"c-str\">&quot;both&quot;</span>`` — auto-retrieve/inject *<span class=\"c-kw\">and</span>* expose ``memory_search``.</span></div>\n<div class=\"c-line\" data-line=\"22\"><span class=\"c-no\">22</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"23\"><span class=\"c-no\">23</span><span class=\"c-src\">ReMe scopes writes by ``session_id``, which <span class=\"c-kw\">is</span> read <span class=\"c-kw\">from</span></span></div>\n<div class=\"c-line\" data-line=\"24\"><span class=\"c-no\">24</span><span class=\"c-src\">``agent.state.session_id`` at hook time (<span class=\"c-kw\">not</span> configured on the</span></div>\n<div class=\"c-line\" data-line=\"25\"><span class=\"c-no\">25</span><span class=\"c-src\">middleware), so it always matches the agent&<span class=\"c-com\">#x27;s own session; search runs</span></span></div>\n<div class=\"c-line\" data-line=\"26\"><span class=\"c-no\">26</span><span class=\"c-src\">over the whole workspace.</span></div>\n<div class=\"c-line\" data-line=\"27\"><span class=\"c-no\">27</span><span class=\"c-src\"><span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"28\"><span class=\"c-no\">28</span><span class=\"c-src\"><span class=\"c-kw\">from</span> __future__ <span class=\"c-kw\">import</span> annotations</span></div>\n<div class=\"c-line\" data-line=\"29\"><span class=\"c-no\">29</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"30\"><span class=\"c-no\">30</span><span class=\"c-src\"><span class=\"c-kw\">import</span> asyncio</span></div>\n<div class=\"c-line\" data-line=\"31\"><span class=\"c-no\">31</span><span class=\"c-src\"><span class=\"c-kw\">from</span> typing <span class=\"c-kw\">import</span> (</span></div>\n<div class=\"c-line\" data-line=\"32\"><span class=\"c-no\">32</span><span class=\"c-src\">    Any,</span></div>\n<div class=\"c-line\" data-line=\"33\"><span class=\"c-no\">33</span><span class=\"c-src\">    AsyncGenerator,</span></div>\n<div class=\"c-line\" data-line=\"34\"><span class=\"c-no\">34</span><span class=\"c-src\">    Callable,</span></div>\n<div class=\"c-line\" data-line=\"35\"><span class=\"c-no\">35</span><span class=\"c-src\">    Literal,</span></div>\n<div class=\"c-line\" data-line=\"36\"><span class=\"c-no\">36</span><span class=\"c-src\">    TYPE_CHECKING,</span></div>\n<div class=\"c-line\" data-line=\"37\"><span class=\"c-no\">37</span><span class=\"c-src\">)</span></div>\n<div class=\"c-line\" data-line=\"38\"><span class=\"c-no\">38</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"39\"><span class=\"c-no\">39</span><span class=\"c-src\"><span class=\"c-kw\">from</span> pydantic <span class=\"c-kw\">import</span> BaseModel, Field</span></div>\n<div class=\"c-line\" data-line=\"40\"><span class=\"c-no\">40</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"41\"><span class=\"c-no\">41</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ..._base <span class=\"c-kw\">import</span> MiddlewareBase</span></div>\n<div class=\"c-line\" data-line=\"42\"><span class=\"c-no\">42</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ...._logging <span class=\"c-kw\">import</span> logger</span></div>\n<div class=\"c-line\" data-line=\"43\"><span class=\"c-no\">43</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ....embedding <span class=\"c-kw\">import</span> EmbeddingModelBase</span></div>\n<div class=\"c-line\" data-line=\"44\"><span class=\"c-no\">44</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ....message <span class=\"c-kw\">import</span> AssistantMsg, HintBlock, Msg</span></div>\n<div class=\"c-line\" data-line=\"45\"><span class=\"c-no\">45</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ....model <span class=\"c-kw\">import</span> ChatModelBase</span></div>\n<div class=\"c-line\" data-line=\"46\"><span class=\"c-no\">46</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ._tools <span class=\"c-kw\">import</span> _build_memory_tools</span></div>\n<div class=\"c-line\" data-line=\"47\"><span class=\"c-no\">47</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ._utils <span class=\"c-kw\">import</span> _extract_memory_texts, _extract_query_text</span></div>\n<div class=\"c-line\" data-line=\"48\"><span class=\"c-no\">48</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"49\"><span class=\"c-no\">49</span><span class=\"c-src\"><span class=\"c-kw\">if</span> TYPE_CHECKING:</span></div>\n<div class=\"c-line\" data-line=\"50\"><span class=\"c-no\">50</span><span class=\"c-src\">    <span class=\"c-kw\">from</span> ....agent <span class=\"c-kw\">import</span> Agent</span></div>\n<div class=\"c-line\" data-line=\"51\"><span class=\"c-no\">51</span><span class=\"c-src\">    <span class=\"c-kw\">from</span> ....tool <span class=\"c-kw\">import</span> ToolBase</span></div>\n<div class=\"c-line\" data-line=\"52\"><span class=\"c-no\">52</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"53\"><span class=\"c-no\">53</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"54\"><span class=\"c-no\">54</span><span class=\"c-src\"><span class=\"c-com\"># Jobs exposed by the ReMe application that this middleware drives.</span></span></div>\n<div class=\"c-line\" data-line=\"55\"><span class=\"c-no\">55</span><span class=\"c-src\">_SEARCH_JOB = <span class=\"c-str\">&quot;search&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"56\"><span class=\"c-no\">56</span><span class=\"c-src\">_AUTO_MEMORY_JOB = <span class=\"c-str\">&quot;auto_memory&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"57\"><span class=\"c-no\">57</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"58\"><span class=\"c-no\">58</span><span class=\"c-src\"><span class=\"c-com\"># ReMe component coordinates for the default chat-model / embedding</span></span></div>\n<div class=\"c-line\" data-line=\"59\"><span class=\"c-no\">59</span><span class=\"c-src\"><span class=\"c-com\"># backends. ReMe starts both eagerly at ``start()`` (the embedding</span></span></div>\n<div class=\"c-line\" data-line=\"60\"><span class=\"c-no\">60</span><span class=\"c-src\"><span class=\"c-com\"># component is wired in even when the default file store searches</span></span></div>\n<div class=\"c-line\" data-line=\"61\"><span class=\"c-no\">61</span><span class=\"c-src\"><span class=\"c-com\"># keyword-only), so an injected model bypasses ReMe building its own</span></span></div>\n<div class=\"c-line\" data-line=\"62\"><span class=\"c-no\">62</span><span class=\"c-src\"><span class=\"c-com\"># from credentials — the same escape hatch for both components.</span></span></div>\n<div class=\"c-line\" data-line=\"63\"><span class=\"c-no\">63</span><span class=\"c-src\">_AS_LLM_COMPONENT = <span class=\"c-str\">&quot;as_llm&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"64\"><span class=\"c-no\">64</span><span class=\"c-src\">_AS_EMBEDDING_COMPONENT = <span class=\"c-str\">&quot;as_embedding&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"65\"><span class=\"c-no\">65</span><span class=\"c-src\">_AS_DEFAULT = <span class=\"c-str\">&quot;default&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"66\"><span class=\"c-no\">66</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"67\"><span class=\"c-no\">67</span><span class=\"c-src\"><span class=\"c-com\"># Header rendered above retrieved memories injected into context.</span></span></div>\n<div class=\"c-line\" data-line=\"68\"><span class=\"c-no\">68</span><span class=\"c-src\">_MEMORY_MSG_NAME = <span class=\"c-str\">&quot;memory&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"69\"><span class=\"c-no\">69</span><span class=\"c-src\">_MEMORY_SECTION_HEADER = <span class=\"c-str\">&quot;## Relevant memories from past conversations&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"70\"><span class=\"c-no\">70</span><span class=\"c-src\">_MEMORY_SECTION_INTRO = (</span></div>\n<div class=\"c-line\" data-line=\"71\"><span class=\"c-no\">71</span><span class=\"c-src\">    <span class=\"c-str\">&quot;The following memories about the user may be relevant. &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"72\"><span class=\"c-no\">72</span><span class=\"c-src\">    <span class=\"c-str\">&quot;Use them only if they are pertinent to the current request.&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"73\"><span class=\"c-no\">73</span><span class=\"c-src\">)</span></div>\n<div class=\"c-line\" data-line=\"74\"><span class=\"c-no\">74</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"75\"><span class=\"c-no\">75</span><span class=\"c-src\"><span class=\"c-com\"># Appended to the system prompt to advertise the search tool to the LLM.</span></span></div>\n<div class=\"c-line\" data-line=\"76\"><span class=\"c-no\">76</span><span class=\"c-src\">_TOOL_INSTRUCTIONS = (</span></div>\n<div class=\"c-line\" data-line=\"77\"><span class=\"c-no\">77</span><span class=\"c-src\">    <span class=\"c-str\">&quot;## Long-term memory\\n\\n&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"78\"><span class=\"c-no\">78</span><span class=\"c-src\">    <span class=\"c-str\">&quot;You have a `memory_search` tool available. Use it whenever the &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"79\"><span class=\"c-no\">79</span><span class=\"c-src\">    <span class=\"c-str\">&quot;current conversation may depend on a durable fact from a past &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"80\"><span class=\"c-no\">80</span><span class=\"c-src\">    <span class=\"c-str\">&quot;session (a preference, a name, a prior decision). Recording memory &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"81\"><span class=\"c-no\">81</span><span class=\"c-src\">    <span class=\"c-str\">&quot;is handled automatically; there is no add tool.&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"82\"><span class=\"c-no\">82</span><span class=\"c-src\">)</span></div>\n<div class=\"c-line\" data-line=\"83\"><span class=\"c-no\">83</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"84\"><span class=\"c-no\">84</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"85\"><span class=\"c-no\">85</span><span class=\"c-src\"><span class=\"c-kw\">class</span> ReMeMiddleware(MiddlewareBase):</span></div>\n<div class=\"c-line\" data-line=\"86\"><span class=\"c-no\">86</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;AgentScope middleware that adds long-term memory backed by</span></div>\n<div class=\"c-line\" data-line=\"87\"><span class=\"c-no\">87</span><span class=\"c-src\">    `ReMe &lt;https://github.com/agentscope-ai/ReMe&gt;`_.</span></div>\n<div class=\"c-line\" data-line=\"88\"><span class=\"c-no\">88</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"89\"><span class=\"c-no\">89</span><span class=\"c-src\">    ReMe <span class=\"c-kw\">is</span> embedded **<span class=\"c-kw\">in</span>-process** (no separate service): the middleware</span></div>\n<div class=\"c-line\" data-line=\"90\"><span class=\"c-no\">90</span><span class=\"c-src\">    instantiates a :<span class=\"c-kw\">class</span>:`reme.ReMe` application whose LLM-backed jobs use</span></div>\n<div class=\"c-line\" data-line=\"91\"><span class=\"c-no\">91</span><span class=\"c-src\">    the ``chat_model`` configured at construction. The app <span class=\"c-kw\">is</span> built <span class=\"c-kw\">and</span></span></div>\n<div class=\"c-line\" data-line=\"92\"><span class=\"c-no\">92</span><span class=\"c-src\">    owned by the middleware — <span class=\"c-kw\">pass</span> ``workspace_dir`` / ``config`` (<span class=\"c-kw\">and</span></span></div>\n<div class=\"c-line\" data-line=\"93\"><span class=\"c-no\">93</span><span class=\"c-src\">    optionally a ``Parameters`` <span class=\"c-kw\">with</span> ``chat_model`` / ``embedding_model``)</span></div>\n<div class=\"c-line\" data-line=\"94\"><span class=\"c-no\">94</span><span class=\"c-src\">    <span class=\"c-kw\">and</span> it <span class=\"c-kw\">is</span> created lazily on first use. When ``chat_model`` <span class=\"c-kw\">is</span> omitted,</span></div>\n<div class=\"c-line\" data-line=\"95\"><span class=\"c-no\">95</span><span class=\"c-src\">    ReMe uses the LLM <span class=\"c-kw\">from</span> its own config/credentials. Providing an</span></div>\n<div class=\"c-line\" data-line=\"96\"><span class=\"c-no\">96</span><span class=\"c-src\">    ``embedding_model`` enables ReMe&<span class=\"c-com\">#x27;s vector store; otherwise search stays</span></span></div>\n<div class=\"c-line\" data-line=\"97\"><span class=\"c-no\">97</span><span class=\"c-src\">    keyword-only.</span></div>\n<div class=\"c-line\" data-line=\"98\"><span class=\"c-no\">98</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"99\"><span class=\"c-no\">99</span><span class=\"c-src\">    The model <span class=\"c-kw\">is</span> fixed at construction (never taken <span class=\"c-kw\">from</span> an agent), so the</span></div>\n<div class=\"c-line\" data-line=\"100\"><span class=\"c-no\">100</span><span class=\"c-src\">    embedded app&<span class=\"c-com\">#x27;s single LLM is well-defined even when one middleware</span></span></div>\n<div class=\"c-line\" data-line=\"101\"><span class=\"c-no\">101</span><span class=\"c-src\">    instance <span class=\"c-kw\">is</span> shared across several agents. Per-conversation state — the</span></div>\n<div class=\"c-line\" data-line=\"102\"><span class=\"c-no\">102</span><span class=\"c-src\">    ReMe ``session_id`` — <span class=\"c-kw\">is</span> instead read live <span class=\"c-kw\">from</span> each agent at hook</span></div>\n<div class=\"c-line\" data-line=\"103\"><span class=\"c-no\">103</span><span class=\"c-src\">    time <span class=\"c-kw\">and</span> never stored, keeping shared use isolated. Background</span></div>\n<div class=\"c-line\" data-line=\"104\"><span class=\"c-no\">104</span><span class=\"c-src\">    retrieval tasks are likewise tracked per ``session_id`` so concurrent</span></div>\n<div class=\"c-line\" data-line=\"105\"><span class=\"c-no\">105</span><span class=\"c-src\">    replies <span class=\"c-kw\">in</span> different sessions never clobber each other&<span class=\"c-com\">#x27;s in-flight</span></span></div>\n<div class=\"c-line\" data-line=\"106\"><span class=\"c-no\">106</span><span class=\"c-src\">    search.</span></div>\n<div class=\"c-line\" data-line=\"107\"><span class=\"c-no\">107</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"108\"><span class=\"c-no\">108</span><span class=\"c-src\">    AgentScope middleware has no framework-managed lifecycle, so the app</span></div>\n<div class=\"c-line\" data-line=\"109\"><span class=\"c-no\">109</span><span class=\"c-src\">    <span class=\"c-kw\">is</span> built once <span class=\"c-kw\">and</span> started lazily on first use (idempotent). Call</span></div>\n<div class=\"c-line\" data-line=\"110\"><span class=\"c-no\">110</span><span class=\"c-src\">    :meth:`close` <span class=\"c-kw\">for</span> explicit teardown of the embedded app.</span></div>\n<div class=\"c-line\" data-line=\"111\"><span class=\"c-no\">111</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"112\"><span class=\"c-no\">112</span><span class=\"c-src\">    Example::</span></div>\n<div class=\"c-line\" data-line=\"113\"><span class=\"c-no\">113</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"114\"><span class=\"c-no\">114</span><span class=\"c-src\">        <span class=\"c-kw\">from</span> agentscope.middleware <span class=\"c-kw\">import</span> ReMeMiddleware</span></div>\n<div class=\"c-line\" data-line=\"115\"><span class=\"c-no\">115</span><span class=\"c-src\">        <span class=\"c-kw\">from</span> agentscope.tool <span class=\"c-kw\">import</span> Toolkit</span></div>\n<div class=\"c-line\" data-line=\"116\"><span class=\"c-no\">116</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"117\"><span class=\"c-no\">117</span><span class=\"c-src\">        mw = ReMeMiddleware(</span></div>\n<div class=\"c-line\" data-line=\"118\"><span class=\"c-no\">118</span><span class=\"c-src\">            workspace_dir=<span class=\"c-str\">&quot;.reme&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"119\"><span class=\"c-no\">119</span><span class=\"c-src\">            parameters=ReMeMiddleware.Parameters(mode=<span class=\"c-str\">&quot;both&quot;</span>),</span></div>\n<div class=\"c-line\" data-line=\"120\"><span class=\"c-no\">120</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"121\"><span class=\"c-no\">121</span><span class=\"c-src\">        agent = Agent(</span></div>\n<div class=\"c-line\" data-line=\"122\"><span class=\"c-no\">122</span><span class=\"c-src\">            ...,</span></div>\n<div class=\"c-line\" data-line=\"123\"><span class=\"c-no\">123</span><span class=\"c-src\">            toolkit=Toolkit(tools=<span class=\"c-kw\">await</span> mw.list_tools()),</span></div>\n<div class=\"c-line\" data-line=\"124\"><span class=\"c-no\">124</span><span class=\"c-src\">            middlewares=[mw],</span></div>\n<div class=\"c-line\" data-line=\"125\"><span class=\"c-no\">125</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"126\"><span class=\"c-no\">126</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"127\"><span class=\"c-no\">127</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"128\"><span class=\"c-no\">128</span><span class=\"c-src\">    <span class=\"c-kw\">class</span> Parameters(BaseModel):</span></div>\n<div class=\"c-line\" data-line=\"129\"><span class=\"c-no\">129</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;User-tunable ReMe memory parameters.</span></div>\n<div class=\"c-line\" data-line=\"130\"><span class=\"c-no\">130</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"131\"><span class=\"c-no\">131</span><span class=\"c-src\">        The agent service parses this schema to render a configuration</span></div>\n<div class=\"c-line\" data-line=\"132\"><span class=\"c-no\">132</span><span class=\"c-src\">        form. Structural wiring (``workspace_dir`` / ``config``) stays on</span></div>\n<div class=\"c-line\" data-line=\"133\"><span class=\"c-no\">133</span><span class=\"c-src\">        the constructor.</span></div>\n<div class=\"c-line\" data-line=\"134\"><span class=\"c-no\">134</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"135\"><span class=\"c-no\">135</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"136\"><span class=\"c-no\">136</span><span class=\"c-src\">        model_config = {<span class=\"c-str\">&quot;arbitrary_types_allowed&quot;</span>: <span class=\"c-kw\">True</span>}</span></div>\n<div class=\"c-line\" data-line=\"137\"><span class=\"c-no\">137</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"138\"><span class=\"c-no\">138</span><span class=\"c-src\">        chat_model: ChatModelBase | <span class=\"c-kw\">None</span> = Field(</span></div>\n<div class=\"c-line\" data-line=\"139\"><span class=\"c-no\">139</span><span class=\"c-src\">            default=<span class=\"c-kw\">None</span>,</span></div>\n<div class=\"c-line\" data-line=\"140\"><span class=\"c-no\">140</span><span class=\"c-src\">            title=<span class=\"c-str\">&quot;Chat Model&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"141\"><span class=\"c-no\">141</span><span class=\"c-src\">            description=(</span></div>\n<div class=\"c-line\" data-line=\"142\"><span class=\"c-no\">142</span><span class=\"c-src\">                <span class=\"c-str\">&quot;AgentScope chat model injected into ReMe&#x27;s default LLM &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"143\"><span class=\"c-no\">143</span><span class=\"c-src\">                <span class=\"c-str\">&quot;component, fixed for the lifetime of the embedded app. &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"144\"><span class=\"c-no\">144</span><span class=\"c-src\">                <span class=\"c-str\">&quot;When `None`, ReMe uses the LLM from its own &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"145\"><span class=\"c-no\">145</span><span class=\"c-src\">                <span class=\"c-str\">&quot;config/credentials. Needed for `auto_memory` write-back.&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"146\"><span class=\"c-no\">146</span><span class=\"c-src\">            ),</span></div>\n<div class=\"c-line\" data-line=\"147\"><span class=\"c-no\">147</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"148\"><span class=\"c-no\">148</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"149\"><span class=\"c-no\">149</span><span class=\"c-src\">        embedding_model: EmbeddingModelBase | <span class=\"c-kw\">None</span> = Field(</span></div>\n<div class=\"c-line\" data-line=\"150\"><span class=\"c-no\">150</span><span class=\"c-src\">            default=<span class=\"c-kw\">None</span>,</span></div>\n<div class=\"c-line\" data-line=\"151\"><span class=\"c-no\">151</span><span class=\"c-src\">            title=<span class=\"c-str\">&quot;Embedding Model&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"152\"><span class=\"c-no\">152</span><span class=\"c-src\">            description=(</span></div>\n<div class=\"c-line\" data-line=\"153\"><span class=\"c-no\">153</span><span class=\"c-src\">                <span class=\"c-str\">&quot;AgentScope embedding model injected into ReMe&#x27;s default &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"154\"><span class=\"c-no\">154</span><span class=\"c-src\">                <span class=\"c-str\">&quot;embedding component, fixed for the lifetime of the embedded &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"155\"><span class=\"c-no\">155</span><span class=\"c-src\">                <span class=\"c-str\">&quot;app. ReMe starts this component eagerly (it is wired into &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"156\"><span class=\"c-no\">156</span><span class=\"c-src\">                <span class=\"c-str\">&quot;the file store even when search is keyword-only), so &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"157\"><span class=\"c-no\">157</span><span class=\"c-src\">                <span class=\"c-str\">&quot;injecting a model bypasses ReMe building its own from &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"158\"><span class=\"c-no\">158</span><span class=\"c-src\">                <span class=\"c-str\">&quot;credentials. When `None`, ReMe uses the embedding backend &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"159\"><span class=\"c-no\">159</span><span class=\"c-src\">                <span class=\"c-str\">&quot;from its own config/credentials.&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"160\"><span class=\"c-no\">160</span><span class=\"c-src\">            ),</span></div>\n<div class=\"c-line\" data-line=\"161\"><span class=\"c-no\">161</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"162\"><span class=\"c-no\">162</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"163\"><span class=\"c-no\">163</span><span class=\"c-src\">        mode: Literal[<span class=\"c-str\">&quot;static_control&quot;</span>, <span class=\"c-str\">&quot;agent_control&quot;</span>, <span class=\"c-str\">&quot;both&quot;</span>] = Field(</span></div>\n<div class=\"c-line\" data-line=\"164\"><span class=\"c-no\">164</span><span class=\"c-src\">            default=<span class=\"c-str\">&quot;both&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"165\"><span class=\"c-no\">165</span><span class=\"c-src\">            title=<span class=\"c-str\">&quot;Retrieval Mode&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"166\"><span class=\"c-no\">166</span><span class=\"c-src\">            description=(</span></div>\n<div class=\"c-line\" data-line=\"167\"><span class=\"c-no\">167</span><span class=\"c-src\">                <span class=\"c-str\">&quot;How the agent retrieves from ReMe (write-back runs &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"168\"><span class=\"c-no\">168</span><span class=\"c-src\">                <span class=\"c-str\">&quot;automatically in every mode). `static_control`: search and &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"169\"><span class=\"c-no\">169</span><span class=\"c-src\">                <span class=\"c-str\">&quot;inject before each reply, no tool. `agent_control`: expose &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"170\"><span class=\"c-no\">170</span><span class=\"c-src\">                <span class=\"c-str\">&quot;the `memory_search` tool, no auto-retrieval. `both`: &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"171\"><span class=\"c-no\">171</span><span class=\"c-src\">                <span class=\"c-str\">&quot;auto-retrieve/inject and expose the tool.&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"172\"><span class=\"c-no\">172</span><span class=\"c-src\">            ),</span></div>\n<div class=\"c-line\" data-line=\"173\"><span class=\"c-no\">173</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"174\"><span class=\"c-no\">174</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"175\"><span class=\"c-no\">175</span><span class=\"c-src\">        top_k: int = Field(</span></div>\n<div class=\"c-line\" data-line=\"176\"><span class=\"c-no\">176</span><span class=\"c-src\">            default=5,</span></div>\n<div class=\"c-line\" data-line=\"177\"><span class=\"c-no\">177</span><span class=\"c-src\">            title=<span class=\"c-str\">&quot;Top K&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"178\"><span class=\"c-no\">178</span><span class=\"c-src\">            description=(</span></div>\n<div class=\"c-line\" data-line=\"179\"><span class=\"c-no\">179</span><span class=\"c-src\">                <span class=\"c-str\">&quot;Max number of memories retrieved per search, and the &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"180\"><span class=\"c-no\">180</span><span class=\"c-src\">                <span class=\"c-str\">&quot;default `limit` advertised by the `memory_search` tool.&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"181\"><span class=\"c-no\">181</span><span class=\"c-src\">            ),</span></div>\n<div class=\"c-line\" data-line=\"182\"><span class=\"c-no\">182</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"183\"><span class=\"c-no\">183</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"184\"><span class=\"c-no\">184</span><span class=\"c-src\">    <span class=\"c-kw\">def</span> __init__(</span></div>\n<div class=\"c-line\" data-line=\"185\"><span class=\"c-no\">185</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"186\"><span class=\"c-no\">186</span><span class=\"c-src\">        *,</span></div>\n<div class=\"c-line\" data-line=\"187\"><span class=\"c-no\">187</span><span class=\"c-src\">        workspace_dir: str = <span class=\"c-str\">&quot;.reme&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"188\"><span class=\"c-no\">188</span><span class=\"c-src\">        config: str = <span class=\"c-str\">&quot;default&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"189\"><span class=\"c-no\">189</span><span class=\"c-src\">        parameters: Parameters | <span class=\"c-kw\">None</span> = <span class=\"c-kw\">None</span>,</span></div>\n<div class=\"c-line\" data-line=\"190\"><span class=\"c-no\">190</span><span class=\"c-src\">    ) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"191\"><span class=\"c-no\">191</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Initialize the ReMe middleware.</span></div>\n<div class=\"c-line\" data-line=\"192\"><span class=\"c-no\">192</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"193\"><span class=\"c-no\">193</span><span class=\"c-src\">        The ReMe ``session_id`` (which scopes write-back memory cards) <span class=\"c-kw\">is</span></span></div>\n<div class=\"c-line\" data-line=\"194\"><span class=\"c-no\">194</span><span class=\"c-src\">        **<span class=\"c-kw\">not</span>** taken here — it <span class=\"c-kw\">is</span> read <span class=\"c-kw\">from</span> ``agent.state.session_id`` at</span></div>\n<div class=\"c-line\" data-line=\"195\"><span class=\"c-no\">195</span><span class=\"c-src\">        hook time (every agent has one; ``AgentState`` generates it),</span></div>\n<div class=\"c-line\" data-line=\"196\"><span class=\"c-no\">196</span><span class=\"c-src\">        mirroring :<span class=\"c-kw\">class</span>:`TracingMiddleware`. To pin a resumable session,</span></div>\n<div class=\"c-line\" data-line=\"197\"><span class=\"c-no\">197</span><span class=\"c-src\">        set the id on the agent (``Agent(state=AgentState(session_id=...))``).</span></div>\n<div class=\"c-line\" data-line=\"198\"><span class=\"c-no\">198</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"199\"><span class=\"c-no\">199</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"200\"><span class=\"c-no\">200</span><span class=\"c-src\">            workspace_dir (`str`, optional):</span></div>\n<div class=\"c-line\" data-line=\"201\"><span class=\"c-no\">201</span><span class=\"c-src\">                ReMe workspace (vault) directory <span class=\"c-kw\">for</span> memory cards <span class=\"c-kw\">and</span></span></div>\n<div class=\"c-line\" data-line=\"202\"><span class=\"c-no\">202</span><span class=\"c-src\">                indexes. Defaults to ``<span class=\"c-str\">&quot;.reme&quot;</span>``.</span></div>\n<div class=\"c-line\" data-line=\"203\"><span class=\"c-no\">203</span><span class=\"c-src\">            config (`str`, optional):</span></div>\n<div class=\"c-line\" data-line=\"204\"><span class=\"c-no\">204</span><span class=\"c-src\">                ReMe config name <span class=\"c-kw\">or</span> path. Defaults to ``<span class=\"c-str\">&quot;default&quot;</span>``</span></div>\n<div class=\"c-line\" data-line=\"205\"><span class=\"c-no\">205</span><span class=\"c-src\">                (ReMe&<span class=\"c-com\">#x27;s bundled ``default.yaml``).</span></span></div>\n<div class=\"c-line\" data-line=\"206\"><span class=\"c-no\">206</span><span class=\"c-src\">            parameters (`ReMeMiddleware.Parameters | <span class=\"c-kw\">None</span>`, optional):</span></div>\n<div class=\"c-line\" data-line=\"207\"><span class=\"c-no\">207</span><span class=\"c-src\">                User-tunable parameters (``chat_model`` / ``embedding_model``</span></div>\n<div class=\"c-line\" data-line=\"208\"><span class=\"c-no\">208</span><span class=\"c-src\">                / ``mode`` / ``top_k``) whose schema the agent service</span></div>\n<div class=\"c-line\" data-line=\"209\"><span class=\"c-no\">209</span><span class=\"c-src\">                renders <span class=\"c-kw\">as</span> a configuration form. When ``<span class=\"c-kw\">None</span>``, defaults are</span></div>\n<div class=\"c-line\" data-line=\"210\"><span class=\"c-no\">210</span><span class=\"c-src\">                used. Providing an ``embedding_model`` also enables ReMe&<span class=\"c-com\">#x27;s</span></span></div>\n<div class=\"c-line\" data-line=\"211\"><span class=\"c-no\">211</span><span class=\"c-src\">                vector store (otherwise search <span class=\"c-kw\">is</span> keyword-only).</span></div>\n<div class=\"c-line\" data-line=\"212\"><span class=\"c-no\">212</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"213\"><span class=\"c-no\">213</span><span class=\"c-src\">        <span class=\"c-com\"># Embedded ReMe application state. The app is built lazily and</span></span></div>\n<div class=\"c-line\" data-line=\"214\"><span class=\"c-no\">214</span><span class=\"c-src\">        <span class=\"c-com\"># started once (idempotent guards), since middleware has no</span></span></div>\n<div class=\"c-line\" data-line=\"215\"><span class=\"c-no\">215</span><span class=\"c-src\">        <span class=\"c-com\"># framework-managed lifecycle. The middleware always owns the app</span></span></div>\n<div class=\"c-line\" data-line=\"216\"><span class=\"c-no\">216</span><span class=\"c-src\">        <span class=\"c-com\"># it builds, so :meth:`close` tears it down.</span></span></div>\n<div class=\"c-line\" data-line=\"217\"><span class=\"c-no\">217</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>._app: Any | <span class=\"c-kw\">None</span> = <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"218\"><span class=\"c-no\">218</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>._started = <span class=\"c-kw\">False</span></span></div>\n<div class=\"c-line\" data-line=\"219\"><span class=\"c-no\">219</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>._workspace_dir = workspace_dir</span></div>\n<div class=\"c-line\" data-line=\"220\"><span class=\"c-no\">220</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>._config = config</span></div>\n<div class=\"c-line\" data-line=\"221\"><span class=\"c-no\">221</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>._parameters = parameters <span class=\"c-kw\">or</span> <span class=\"c-kw\">self</span>.Parameters()</span></div>\n<div class=\"c-line\" data-line=\"222\"><span class=\"c-no\">222</span><span class=\"c-src\">        <span class=\"c-com\"># In-flight background retrieval per session (started in ``on_reply``,</span></span></div>\n<div class=\"c-line\" data-line=\"223\"><span class=\"c-no\">223</span><span class=\"c-src\">        <span class=\"c-com\"># consumed/injected in ``on_reasoning``, cleaned up in ``on_reply``&#x27;s</span></span></div>\n<div class=\"c-line\" data-line=\"224\"><span class=\"c-no\">224</span><span class=\"c-src\">        <span class=\"c-com\"># finally). Keyed by ``session_id`` so one middleware shared across</span></span></div>\n<div class=\"c-line\" data-line=\"225\"><span class=\"c-no\">225</span><span class=\"c-src\">        <span class=\"c-com\"># agents keeps each session&#x27;s retrieval isolated — a concurrent reply</span></span></div>\n<div class=\"c-line\" data-line=\"226\"><span class=\"c-no\">226</span><span class=\"c-src\">        <span class=\"c-com\"># in another session never clobbers this one&#x27;s task.</span></span></div>\n<div class=\"c-line\" data-line=\"227\"><span class=\"c-no\">227</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>._retrieval_tasks: dict[Any, asyncio.Task] = {}</span></div>\n<div class=\"c-line\" data-line=\"228\"><span class=\"c-no\">228</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"229\"><span class=\"c-no\">229</span><span class=\"c-src\">    <span class=\"c-com\"># ==================================================================</span></span></div>\n<div class=\"c-line\" data-line=\"230\"><span class=\"c-no\">230</span><span class=\"c-src\">    <span class=\"c-com\"># Embedded ReMe application lifecycle</span></span></div>\n<div class=\"c-line\" data-line=\"231\"><span class=\"c-no\">231</span><span class=\"c-src\">    <span class=\"c-com\"># ==================================================================</span></span></div>\n<div class=\"c-line\" data-line=\"232\"><span class=\"c-no\">232</span><span class=\"c-src\">    <span class=\"c-kw\">def</span> _build_app(<span class=\"c-kw\">self</span>) -&gt; Any:</span></div>\n<div class=\"c-line\" data-line=\"233\"><span class=\"c-no\">233</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Lazily build the embedded :<span class=\"c-kw\">class</span>:`reme.ReMe` application.</span></div>\n<div class=\"c-line\" data-line=\"234\"><span class=\"c-no\">234</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"235\"><span class=\"c-no\">235</span><span class=\"c-src\">        Raises:</span></div>\n<div class=\"c-line\" data-line=\"236\"><span class=\"c-no\">236</span><span class=\"c-src\">            ImportError:</span></div>\n<div class=\"c-line\" data-line=\"237\"><span class=\"c-no\">237</span><span class=\"c-src\">                If ``reme-ai`` <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> installed.</span></div>\n<div class=\"c-line\" data-line=\"238\"><span class=\"c-no\">238</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"239\"><span class=\"c-no\">239</span><span class=\"c-src\">        <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"240\"><span class=\"c-no\">240</span><span class=\"c-src\">            <span class=\"c-kw\">from</span> reme <span class=\"c-kw\">import</span> ReMe</span></div>\n<div class=\"c-line\" data-line=\"241\"><span class=\"c-no\">241</span><span class=\"c-src\">            <span class=\"c-kw\">from</span> reme.config <span class=\"c-kw\">import</span> resolve_app_config</span></div>\n<div class=\"c-line\" data-line=\"242\"><span class=\"c-no\">242</span><span class=\"c-src\">        <span class=\"c-kw\">except</span> ImportError <span class=\"c-kw\">as</span> e:  <span class=\"c-com\"># pragma: no cover - import guard</span></span></div>\n<div class=\"c-line\" data-line=\"243\"><span class=\"c-no\">243</span><span class=\"c-src\">            <span class=\"c-kw\">raise</span> ImportError(</span></div>\n<div class=\"c-line\" data-line=\"244\"><span class=\"c-no\">244</span><span class=\"c-src\">                <span class=\"c-str\">&quot;ReMeMiddleware requires the `reme-ai` package. Install &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"245\"><span class=\"c-no\">245</span><span class=\"c-src\">                <span class=\"c-str\">&#x27;it with `pip install &quot;agentscope[reme]&quot;` (or &#x27;</span></span></div>\n<div class=\"c-line\" data-line=\"246\"><span class=\"c-no\">246</span><span class=\"c-src\">                <span class=\"c-str\">&quot;`pip install reme-ai`).&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"247\"><span class=\"c-no\">247</span><span class=\"c-src\">            ) <span class=\"c-kw\">from</span> e</span></div>\n<div class=\"c-line\" data-line=\"248\"><span class=\"c-no\">248</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"249\"><span class=\"c-no\">249</span><span class=\"c-src\">        app_kwargs: dict[str, Any] = {</span></div>\n<div class=\"c-line\" data-line=\"250\"><span class=\"c-no\">250</span><span class=\"c-src\">            <span class=\"c-str\">&quot;config&quot;</span>: <span class=\"c-kw\">self</span>._config,</span></div>\n<div class=\"c-line\" data-line=\"251\"><span class=\"c-no\">251</span><span class=\"c-src\">            <span class=\"c-str\">&quot;workspace_dir&quot;</span>: <span class=\"c-kw\">self</span>._workspace_dir,</span></div>\n<div class=\"c-line\" data-line=\"252\"><span class=\"c-no\">252</span><span class=\"c-src\">            <span class=\"c-str\">&quot;enable_logo&quot;</span>: <span class=\"c-kw\">False</span>,</span></div>\n<div class=\"c-line\" data-line=\"253\"><span class=\"c-no\">253</span><span class=\"c-src\">            <span class=\"c-str\">&quot;log_to_console&quot;</span>: <span class=\"c-kw\">False</span>,</span></div>\n<div class=\"c-line\" data-line=\"254\"><span class=\"c-no\">254</span><span class=\"c-src\">        }</span></div>\n<div class=\"c-line\" data-line=\"255\"><span class=\"c-no\">255</span><span class=\"c-src\">        <span class=\"c-com\"># An embedding model turns on ReMe&#x27;s vector store: the bundled</span></span></div>\n<div class=\"c-line\" data-line=\"256\"><span class=\"c-no\">256</span><span class=\"c-src\">        <span class=\"c-com\"># ``default`` config ships it off (BM25 keyword search only), so we</span></span></div>\n<div class=\"c-line\" data-line=\"257\"><span class=\"c-no\">257</span><span class=\"c-src\">        <span class=\"c-com\"># wire the file store to the default embedding store when — and</span></span></div>\n<div class=\"c-line\" data-line=\"258\"><span class=\"c-no\">258</span><span class=\"c-src\">        <span class=\"c-com\"># only when — a model is available to build the vectors.</span></span></div>\n<div class=\"c-line\" data-line=\"259\"><span class=\"c-no\">259</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">self</span>._parameters.embedding_model <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"260\"><span class=\"c-no\">260</span><span class=\"c-src\">            app_kwargs[<span class=\"c-str\">&quot;components&quot;</span>] = {</span></div>\n<div class=\"c-line\" data-line=\"261\"><span class=\"c-no\">261</span><span class=\"c-src\">                <span class=\"c-str\">&quot;file_store&quot;</span>: {<span class=\"c-str\">&quot;default&quot;</span>: {<span class=\"c-str\">&quot;embedding_store&quot;</span>: <span class=\"c-str\">&quot;default&quot;</span>}},</span></div>\n<div class=\"c-line\" data-line=\"262\"><span class=\"c-no\">262</span><span class=\"c-src\">            }</span></div>\n<div class=\"c-line\" data-line=\"263\"><span class=\"c-no\">263</span><span class=\"c-src\">        app_config = resolve_app_config(**app_kwargs)</span></div>\n<div class=\"c-line\" data-line=\"264\"><span class=\"c-no\">264</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> ReMe(**app_config)</span></div>\n<div class=\"c-line\" data-line=\"265\"><span class=\"c-no\">265</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"266\"><span class=\"c-no\">266</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> _ensure_started(<span class=\"c-kw\">self</span>) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"267\"><span class=\"c-no\">267</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Build (<span class=\"c-kw\">if</span> needed) <span class=\"c-kw\">and</span> start the embedded app (idempotent).</span></div>\n<div class=\"c-line\" data-line=\"268\"><span class=\"c-no\">268</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"269\"><span class=\"c-no\">269</span><span class=\"c-src\">        The configured ``chat_model`` / ``embedding_model`` are injected</span></div>\n<div class=\"c-line\" data-line=\"270\"><span class=\"c-no\">270</span><span class=\"c-src\">        into ReMe&<span class=\"c-com\">#x27;s default LLM and embedding components **before** the</span></span></div>\n<div class=\"c-line\" data-line=\"271\"><span class=\"c-no\">271</span><span class=\"c-src\">        one-time ``start()`` (ReMe&<span class=\"c-com\">#x27;s ``BaseAsLLM._start`` /</span></span></div>\n<div class=\"c-line\" data-line=\"272\"><span class=\"c-no\">272</span><span class=\"c-src\">        ``BaseAsEmbedding._start`` skip building a model <span class=\"c-kw\">from</span> credentials</span></div>\n<div class=\"c-line\" data-line=\"273\"><span class=\"c-no\">273</span><span class=\"c-src\">        when ``model`` <span class=\"c-kw\">is</span> already set). Both are fixed at construction —</span></div>\n<div class=\"c-line\" data-line=\"274\"><span class=\"c-no\">274</span><span class=\"c-src\">        never taken <span class=\"c-kw\">from</span> an agent — so the embedded app (which has a</span></div>\n<div class=\"c-line\" data-line=\"275\"><span class=\"c-no\">275</span><span class=\"c-src\">        single LLM <span class=\"c-kw\">and</span> a single embedding component) has one well-defined</span></div>\n<div class=\"c-line\" data-line=\"276\"><span class=\"c-no\">276</span><span class=\"c-src\">        model each regardless of how many agents share this middleware.</span></div>\n<div class=\"c-line\" data-line=\"277\"><span class=\"c-no\">277</span><span class=\"c-src\">        When either <span class=\"c-kw\">is</span> ``<span class=\"c-kw\">None</span>``, ReMe falls back to the backend configured</span></div>\n<div class=\"c-line\" data-line=\"278\"><span class=\"c-no\">278</span><span class=\"c-src\">        <span class=\"c-kw\">in</span> its own config/credentials.</span></div>\n<div class=\"c-line\" data-line=\"279\"><span class=\"c-no\">279</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"280\"><span class=\"c-no\">280</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">self</span>._app <span class=\"c-kw\">is</span> <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"281\"><span class=\"c-no\">281</span><span class=\"c-src\">            <span class=\"c-kw\">self</span>._app = <span class=\"c-kw\">self</span>._build_app()</span></div>\n<div class=\"c-line\" data-line=\"282\"><span class=\"c-no\">282</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> <span class=\"c-kw\">self</span>._started:</span></div>\n<div class=\"c-line\" data-line=\"283\"><span class=\"c-no\">283</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> <span class=\"c-kw\">self</span>._parameters.chat_model <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"284\"><span class=\"c-no\">284</span><span class=\"c-src\">                <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._app.update_component(</span></div>\n<div class=\"c-line\" data-line=\"285\"><span class=\"c-no\">285</span><span class=\"c-src\">                    _AS_LLM_COMPONENT,</span></div>\n<div class=\"c-line\" data-line=\"286\"><span class=\"c-no\">286</span><span class=\"c-src\">                    _AS_DEFAULT,</span></div>\n<div class=\"c-line\" data-line=\"287\"><span class=\"c-no\">287</span><span class=\"c-src\">                    model=<span class=\"c-kw\">self</span>._parameters.chat_model,</span></div>\n<div class=\"c-line\" data-line=\"288\"><span class=\"c-no\">288</span><span class=\"c-src\">                )</span></div>\n<div class=\"c-line\" data-line=\"289\"><span class=\"c-no\">289</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> <span class=\"c-kw\">self</span>._parameters.embedding_model <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"290\"><span class=\"c-no\">290</span><span class=\"c-src\">                <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._app.update_component(</span></div>\n<div class=\"c-line\" data-line=\"291\"><span class=\"c-no\">291</span><span class=\"c-src\">                    _AS_EMBEDDING_COMPONENT,</span></div>\n<div class=\"c-line\" data-line=\"292\"><span class=\"c-no\">292</span><span class=\"c-src\">                    _AS_DEFAULT,</span></div>\n<div class=\"c-line\" data-line=\"293\"><span class=\"c-no\">293</span><span class=\"c-src\">                    model=<span class=\"c-kw\">self</span>._parameters.embedding_model,</span></div>\n<div class=\"c-line\" data-line=\"294\"><span class=\"c-no\">294</span><span class=\"c-src\">                )</span></div>\n<div class=\"c-line\" data-line=\"295\"><span class=\"c-no\">295</span><span class=\"c-src\">            <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._app.start()</span></div>\n<div class=\"c-line\" data-line=\"296\"><span class=\"c-no\">296</span><span class=\"c-src\">            <span class=\"c-kw\">self</span>._started = <span class=\"c-kw\">True</span></span></div>\n<div class=\"c-line\" data-line=\"297\"><span class=\"c-no\">297</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"298\"><span class=\"c-no\">298</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> close(<span class=\"c-kw\">self</span>) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"299\"><span class=\"c-no\">299</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Close the embedded ReMe app.</span></div>\n<div class=\"c-line\" data-line=\"300\"><span class=\"c-no\">300</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"301\"><span class=\"c-no\">301</span><span class=\"c-src\">        AgentScope does <span class=\"c-kw\">not</span> manage middleware lifecycle, so call this</span></div>\n<div class=\"c-line\" data-line=\"302\"><span class=\"c-no\">302</span><span class=\"c-src\">        explicitly <span class=\"c-kw\">for</span> clean teardown (e.g. on application shutdown).</span></div>\n<div class=\"c-line\" data-line=\"303\"><span class=\"c-no\">303</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"304\"><span class=\"c-no\">304</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">self</span>._app <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> <span class=\"c-kw\">None</span> <span class=\"c-kw\">and</span> <span class=\"c-kw\">self</span>._started:</span></div>\n<div class=\"c-line\" data-line=\"305\"><span class=\"c-no\">305</span><span class=\"c-src\">            <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._app.close()</span></div>\n<div class=\"c-line\" data-line=\"306\"><span class=\"c-no\">306</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>._started = <span class=\"c-kw\">False</span></span></div>\n<div class=\"c-line\" data-line=\"307\"><span class=\"c-no\">307</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"308\"><span class=\"c-no\">308</span><span class=\"c-src\">    @staticmethod</span></div>\n<div class=\"c-line\" data-line=\"309\"><span class=\"c-no\">309</span><span class=\"c-src\">    <span class=\"c-kw\">def</span> _session_id_of(agent: <span class=\"c-str\">&quot;Agent&quot;</span>) -&gt; str | <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"310\"><span class=\"c-no\">310</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Read the ReMe ``session_id`` live <span class=\"c-kw\">from</span> the agent.</span></div>\n<div class=\"c-line\" data-line=\"311\"><span class=\"c-no\">311</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"312\"><span class=\"c-no\">312</span><span class=\"c-src\">        ReMe scopes write-back memory cards by ``session_id``. It <span class=\"c-kw\">is</span> read</span></div>\n<div class=\"c-line\" data-line=\"313\"><span class=\"c-no\">313</span><span class=\"c-src\">        <span class=\"c-kw\">from</span> ``agent.state.session_id`` at hook time <span class=\"c-kw\">and</span> threaded through</span></div>\n<div class=\"c-line\" data-line=\"314\"><span class=\"c-no\">314</span><span class=\"c-src\">        per call — **never** stored on the middleware — so a single</span></div>\n<div class=\"c-line\" data-line=\"315\"><span class=\"c-no\">315</span><span class=\"c-src\">        instance shared across agents keeps each conversation&<span class=\"c-com\">#x27;s writes</span></span></div>\n<div class=\"c-line\" data-line=\"316\"><span class=\"c-no\">316</span><span class=\"c-src\">        isolated. Mirrors how :<span class=\"c-kw\">class</span>:`TracingMiddleware` sources the</span></div>\n<div class=\"c-line\" data-line=\"317\"><span class=\"c-no\">317</span><span class=\"c-src\">        session <span class=\"c-kw\">from</span> the agent rather than <span class=\"c-kw\">from</span> middleware config.</span></div>\n<div class=\"c-line\" data-line=\"318\"><span class=\"c-no\">318</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"319\"><span class=\"c-no\">319</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> getattr(getattr(agent, <span class=\"c-str\">&quot;state&quot;</span>, <span class=\"c-kw\">None</span>), <span class=\"c-str\">&quot;session_id&quot;</span>, <span class=\"c-kw\">None</span>)</span></div>\n<div class=\"c-line\" data-line=\"320\"><span class=\"c-no\">320</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"321\"><span class=\"c-no\">321</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"322\"><span class=\"c-no\">322</span><span class=\"c-src\">    <span class=\"c-com\"># Hook: on_reply</span></span></div>\n<div class=\"c-line\" data-line=\"323\"><span class=\"c-no\">323</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"324\"><span class=\"c-no\">324</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> on_reply(</span></div>\n<div class=\"c-line\" data-line=\"325\"><span class=\"c-no\">325</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"326\"><span class=\"c-no\">326</span><span class=\"c-src\">        agent: <span class=\"c-str\">&quot;Agent&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"327\"><span class=\"c-no\">327</span><span class=\"c-src\">        input_kwargs: dict,</span></div>\n<div class=\"c-line\" data-line=\"328\"><span class=\"c-no\">328</span><span class=\"c-src\">        next_handler: Callable[..., AsyncGenerator],</span></div>\n<div class=\"c-line\" data-line=\"329\"><span class=\"c-no\">329</span><span class=\"c-src\">    ) -&gt; AsyncGenerator:</span></div>\n<div class=\"c-line\" data-line=\"330\"><span class=\"c-no\">330</span><span class=\"c-src\">        session_id = <span class=\"c-kw\">self</span>._session_id_of(agent)</span></div>\n<div class=\"c-line\" data-line=\"331\"><span class=\"c-no\">331</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"332\"><span class=\"c-no\">332</span><span class=\"c-src\">        <span class=\"c-com\"># Kick off retrieval (static_control / both only) concurrently with</span></span></div>\n<div class=\"c-line\" data-line=\"333\"><span class=\"c-no\">333</span><span class=\"c-src\">        <span class=\"c-com\"># the reply. It runs in the background while the agent ingests input</span></span></div>\n<div class=\"c-line\" data-line=\"334\"><span class=\"c-no\">334</span><span class=\"c-src\">        <span class=\"c-com\"># and starts reasoning; ``on_reasoning`` injects the result once the</span></span></div>\n<div class=\"c-line\" data-line=\"335\"><span class=\"c-no\">335</span><span class=\"c-src\">        <span class=\"c-com\"># task finishes. Write the new exchange back afterwards in every mode.</span></span></div>\n<div class=\"c-line\" data-line=\"336\"><span class=\"c-no\">336</span><span class=\"c-src\">        inputs = input_kwargs.get(<span class=\"c-str\">&quot;inputs&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"337\"><span class=\"c-no\">337</span><span class=\"c-src\">        query_text = _extract_query_text(inputs)</span></div>\n<div class=\"c-line\" data-line=\"338\"><span class=\"c-no\">338</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"339\"><span class=\"c-no\">339</span><span class=\"c-src\">        <span class=\"c-com\"># Discard any stale task left for this session (a previous turn that</span></span></div>\n<div class=\"c-line\" data-line=\"340\"><span class=\"c-no\">340</span><span class=\"c-src\">        <span class=\"c-com\"># never reached its finally is unexpected, but never leak one).</span></span></div>\n<div class=\"c-line\" data-line=\"341\"><span class=\"c-no\">341</span><span class=\"c-src\">        stale = <span class=\"c-kw\">self</span>._retrieval_tasks.pop(session_id, <span class=\"c-kw\">None</span>)</span></div>\n<div class=\"c-line\" data-line=\"342\"><span class=\"c-no\">342</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> stale <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> <span class=\"c-kw\">None</span> <span class=\"c-kw\">and</span> <span class=\"c-kw\">not</span> stale.done():</span></div>\n<div class=\"c-line\" data-line=\"343\"><span class=\"c-no\">343</span><span class=\"c-src\">            stale.cancel()</span></div>\n<div class=\"c-line\" data-line=\"344\"><span class=\"c-no\">344</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">self</span>._parameters.mode != <span class=\"c-str\">&quot;agent_control&quot;</span> <span class=\"c-kw\">and</span> query_text:</span></div>\n<div class=\"c-line\" data-line=\"345\"><span class=\"c-no\">345</span><span class=\"c-src\">            <span class=\"c-kw\">self</span>._retrieval_tasks[session_id] = asyncio.create_task(</span></div>\n<div class=\"c-line\" data-line=\"346\"><span class=\"c-no\">346</span><span class=\"c-src\">                <span class=\"c-kw\">self</span>._search(query_text),</span></div>\n<div class=\"c-line\" data-line=\"347\"><span class=\"c-no\">347</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"348\"><span class=\"c-no\">348</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"349\"><span class=\"c-no\">349</span><span class=\"c-src\">        <span class=\"c-com\"># Snapshot the context BEFORE the turn so the write-back persists</span></span></div>\n<div class=\"c-line\" data-line=\"350\"><span class=\"c-no\">350</span><span class=\"c-src\">        <span class=\"c-com\"># only this turn\u0000131\u0000s ``auto_memory`` consumes the</span></span></div>\n<div class=\"c-line\" data-line=\"351\"><span class=\"c-no\">351</span><span class=\"c-src\">        <span class=\"c-com\"># incremental exchange, whereas ``agent.state.context`` is the full</span></span></div>\n<div class=\"c-line\" data-line=\"352\"><span class=\"c-no\">352</span><span class=\"c-src\">        <span class=\"c-com\"># accumulated history — so we diff by message id (below) rather than</span></span></div>\n<div class=\"c-line\" data-line=\"353\"><span class=\"c-no\">353</span><span class=\"c-src\">        <span class=\"c-com\"># sending the whole context, which would re-feed every prior turn.</span></span></div>\n<div class=\"c-line\" data-line=\"354\"><span class=\"c-no\">354</span><span class=\"c-src\">        <span class=\"c-com\"># Taking the increment (not just the final message) still captures</span></span></div>\n<div class=\"c-line\" data-line=\"355\"><span class=\"c-no\">355</span><span class=\"c-src\">        <span class=\"c-com\"># every step of the turn — user input, each assistant step, and</span></span></div>\n<div class=\"c-line\" data-line=\"356\"><span class=\"c-no\">356</span><span class=\"c-src\">        <span class=\"c-com\"># every tool call / tool result — which the agent records on</span></span></div>\n<div class=\"c-line\" data-line=\"357\"><span class=\"c-no\">357</span><span class=\"c-src\">        <span class=\"c-com\"># ``state.context`` via ``_save_to_context`` but does not all yield</span></span></div>\n<div class=\"c-line\" data-line=\"358\"><span class=\"c-no\">358</span><span class=\"c-src\">        <span class=\"c-com\"># on the stream (only the final answer is yielded).</span></span></div>\n<div class=\"c-line\" data-line=\"359\"><span class=\"c-no\">359</span><span class=\"c-src\">        pre_ids = {m.id <span class=\"c-kw\">for</span> m <span class=\"c-kw\">in</span> agent.state.context <span class=\"c-kw\">if</span> isinstance(m, Msg)}</span></div>\n<div class=\"c-line\" data-line=\"360\"><span class=\"c-no\">360</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"361\"><span class=\"c-no\">361</span><span class=\"c-src\">        <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"362\"><span class=\"c-no\">362</span><span class=\"c-src\">            <span class=\"c-kw\">async</span> <span class=\"c-kw\">for</span> item <span class=\"c-kw\">in</span> next_handler(**input_kwargs):</span></div>\n<div class=\"c-line\" data-line=\"363\"><span class=\"c-no\">363</span><span class=\"c-src\">                <span class=\"c-kw\">yield</span> item</span></div>\n<div class=\"c-line\" data-line=\"364\"><span class=\"c-no\">364</span><span class=\"c-src\">        <span class=\"c-kw\">finally</span>:</span></div>\n<div class=\"c-line\" data-line=\"365\"><span class=\"c-no\">365</span><span class=\"c-src\">            <span class=\"c-com\"># Retrieval may still be running (or its hint may never have been</span></span></div>\n<div class=\"c-line\" data-line=\"366\"><span class=\"c-no\">366</span><span class=\"c-src\">            <span class=\"c-com\"># injected — e.g. a single-shot reply that finished before the</span></span></div>\n<div class=\"c-line\" data-line=\"367\"><span class=\"c-no\">367</span><span class=\"c-src\">            <span class=\"c-com\"># task did). Consume this session&#x27;s task so none is orphaned.</span></span></div>\n<div class=\"c-line\" data-line=\"368\"><span class=\"c-no\">368</span><span class=\"c-src\">            task = <span class=\"c-kw\">self</span>._retrieval_tasks.pop(session_id, <span class=\"c-kw\">None</span>)</span></div>\n<div class=\"c-line\" data-line=\"369\"><span class=\"c-no\">369</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> task <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> <span class=\"c-kw\">None</span> <span class=\"c-kw\">and</span> <span class=\"c-kw\">not</span> task.done():</span></div>\n<div class=\"c-line\" data-line=\"370\"><span class=\"c-no\">370</span><span class=\"c-src\">                task.cancel()</span></div>\n<div class=\"c-line\" data-line=\"371\"><span class=\"c-no\">371</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> task <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"372\"><span class=\"c-no\">372</span><span class=\"c-src\">                <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"373\"><span class=\"c-no\">373</span><span class=\"c-src\">                    <span class=\"c-kw\">await</span> task</span></div>\n<div class=\"c-line\" data-line=\"374\"><span class=\"c-no\">374</span><span class=\"c-src\">                <span class=\"c-kw\">except</span> (asyncio.CancelledError, Exception):  <span class=\"c-com\"># noqa: BLE001</span></span></div>\n<div class=\"c-line\" data-line=\"375\"><span class=\"c-no\">375</span><span class=\"c-src\">                    <span class=\"c-kw\">pass</span></span></div>\n<div class=\"c-line\" data-line=\"376\"><span class=\"c-no\">376</span><span class=\"c-src\">            <span class=\"c-com\"># This turn&#x27;s new messages only: everything now present that</span></span></div>\n<div class=\"c-line\" data-line=\"377\"><span class=\"c-no\">377</span><span class=\"c-src\">            <span class=\"c-com\"># was not before, minus any memory hint we injected (matched by</span></span></div>\n<div class=\"c-line\" data-line=\"378\"><span class=\"c-no\">378</span><span class=\"c-src\">            <span class=\"c-com\"># its reserved name, since injection happens in ``on_reasoning``).</span></span></div>\n<div class=\"c-line\" data-line=\"379\"><span class=\"c-no\">379</span><span class=\"c-src\">            increment = [</span></div>\n<div class=\"c-line\" data-line=\"380\"><span class=\"c-no\">380</span><span class=\"c-src\">                m</span></div>\n<div class=\"c-line\" data-line=\"381\"><span class=\"c-no\">381</span><span class=\"c-src\">                <span class=\"c-kw\">for</span> m <span class=\"c-kw\">in</span> agent.state.context</span></div>\n<div class=\"c-line\" data-line=\"382\"><span class=\"c-no\">382</span><span class=\"c-src\">                <span class=\"c-kw\">if</span> isinstance(m, Msg)</span></div>\n<div class=\"c-line\" data-line=\"383\"><span class=\"c-no\">383</span><span class=\"c-src\">                <span class=\"c-kw\">and</span> m.id <span class=\"c-kw\">not</span> <span class=\"c-kw\">in</span> pre_ids</span></div>\n<div class=\"c-line\" data-line=\"384\"><span class=\"c-no\">384</span><span class=\"c-src\">                <span class=\"c-kw\">and</span> getattr(m, <span class=\"c-str\">&quot;name&quot;</span>, <span class=\"c-kw\">None</span>) != _MEMORY_MSG_NAME</span></div>\n<div class=\"c-line\" data-line=\"385\"><span class=\"c-no\">385</span><span class=\"c-src\">            ]</span></div>\n<div class=\"c-line\" data-line=\"386\"><span class=\"c-no\">386</span><span class=\"c-src\">            <span class=\"c-com\"># Only persist a real exchange: a genuine user turn plus at</span></span></div>\n<div class=\"c-line\" data-line=\"387\"><span class=\"c-no\">387</span><span class=\"c-src\">            <span class=\"c-com\"># least one non-empty assistant message produced this turn.</span></span></div>\n<div class=\"c-line\" data-line=\"388\"><span class=\"c-no\">388</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> query_text <span class=\"c-kw\">and</span> any(</span></div>\n<div class=\"c-line\" data-line=\"389\"><span class=\"c-no\">389</span><span class=\"c-src\">                m.role == <span class=\"c-str\">&quot;assistant&quot;</span> <span class=\"c-kw\">and</span> m.get_text_content()</span></div>\n<div class=\"c-line\" data-line=\"390\"><span class=\"c-no\">390</span><span class=\"c-src\">                <span class=\"c-kw\">for</span> m <span class=\"c-kw\">in</span> increment</span></div>\n<div class=\"c-line\" data-line=\"391\"><span class=\"c-no\">391</span><span class=\"c-src\">            ):</span></div>\n<div class=\"c-line\" data-line=\"392\"><span class=\"c-no\">392</span><span class=\"c-src\">                <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._write_back(increment, session_id)</span></div>\n<div class=\"c-line\" data-line=\"393\"><span class=\"c-no\">393</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"394\"><span class=\"c-no\">394</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"395\"><span class=\"c-no\">395</span><span class=\"c-src\">    <span class=\"c-com\"># Hook: on_reasoning (inject retrieved memories once ready)</span></span></div>\n<div class=\"c-line\" data-line=\"396\"><span class=\"c-no\">396</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"397\"><span class=\"c-no\">397</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> on_reasoning(</span></div>\n<div class=\"c-line\" data-line=\"398\"><span class=\"c-no\">398</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"399\"><span class=\"c-no\">399</span><span class=\"c-src\">        agent: <span class=\"c-str\">&quot;Agent&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"400\"><span class=\"c-no\">400</span><span class=\"c-src\">        input_kwargs: dict,</span></div>\n<div class=\"c-line\" data-line=\"401\"><span class=\"c-no\">401</span><span class=\"c-src\">        next_handler: Callable[..., AsyncGenerator],</span></div>\n<div class=\"c-line\" data-line=\"402\"><span class=\"c-no\">402</span><span class=\"c-src\">    ) -&gt; AsyncGenerator:</span></div>\n<div class=\"c-line\" data-line=\"403\"><span class=\"c-no\">403</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Inject background-retrieved memories before a reasoning step.</span></div>\n<div class=\"c-line\" data-line=\"404\"><span class=\"c-no\">404</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"405\"><span class=\"c-no\">405</span><span class=\"c-src\">        The search started <span class=\"c-kw\">in</span> :meth:`on_reply` runs concurrently; this hook</span></div>\n<div class=\"c-line\" data-line=\"406\"><span class=\"c-no\">406</span><span class=\"c-src\">        polls it before each reasoning step <span class=\"c-kw\">and</span>, once it <span class=\"c-kw\">is</span> finished, appends</span></div>\n<div class=\"c-line\" data-line=\"407\"><span class=\"c-no\">407</span><span class=\"c-src\">        the retrieved memories to the agent&<span class=\"c-com\">#x27;s context so the *next* model</span></span></div>\n<div class=\"c-line\" data-line=\"408\"><span class=\"c-no\">408</span><span class=\"c-src\">        call sees them. This <span class=\"c-kw\">is</span> best-effort: a single-shot reply (one model</span></div>\n<div class=\"c-line\" data-line=\"409\"><span class=\"c-no\">409</span><span class=\"c-src\">        call) may finish before retrieval does, <span class=\"c-kw\">in</span> which case the hint <span class=\"c-kw\">is</span></span></div>\n<div class=\"c-line\" data-line=\"410\"><span class=\"c-no\">410</span><span class=\"c-src\">        skipped <span class=\"c-kw\">for</span> that turn — the same trade-off <span class=\"c-kw\">as</span></span></div>\n<div class=\"c-line\" data-line=\"411\"><span class=\"c-no\">411</span><span class=\"c-src\">        :<span class=\"c-kw\">class</span>:`AgenticMemoryMiddleware`.</span></div>\n<div class=\"c-line\" data-line=\"412\"><span class=\"c-no\">412</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"413\"><span class=\"c-no\">413</span><span class=\"c-src\">        session_id = <span class=\"c-kw\">self</span>._session_id_of(agent)</span></div>\n<div class=\"c-line\" data-line=\"414\"><span class=\"c-no\">414</span><span class=\"c-src\">        task = <span class=\"c-kw\">self</span>._retrieval_tasks.get(session_id)</span></div>\n<div class=\"c-line\" data-line=\"415\"><span class=\"c-no\">415</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> task <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> <span class=\"c-kw\">None</span> <span class=\"c-kw\">and</span> task.done():</span></div>\n<div class=\"c-line\" data-line=\"416\"><span class=\"c-no\">416</span><span class=\"c-src\">            <span class=\"c-kw\">self</span>._retrieval_tasks.pop(session_id, <span class=\"c-kw\">None</span>)</span></div>\n<div class=\"c-line\" data-line=\"417\"><span class=\"c-no\">417</span><span class=\"c-src\">            <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"418\"><span class=\"c-no\">418</span><span class=\"c-src\">                memories = task.result()</span></div>\n<div class=\"c-line\" data-line=\"419\"><span class=\"c-no\">419</span><span class=\"c-src\">            <span class=\"c-kw\">except</span> (asyncio.CancelledError, Exception) <span class=\"c-kw\">as</span> e:  <span class=\"c-com\"># noqa: BLE001</span></span></div>\n<div class=\"c-line\" data-line=\"420\"><span class=\"c-no\">420</span><span class=\"c-src\">                memories = []</span></div>\n<div class=\"c-line\" data-line=\"421\"><span class=\"c-no\">421</span><span class=\"c-src\">                logger.warning(<span class=\"c-str\">&quot;ReMe search failed: %s&quot;</span>, e)</span></div>\n<div class=\"c-line\" data-line=\"422\"><span class=\"c-no\">422</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> memories:</span></div>\n<div class=\"c-line\" data-line=\"423\"><span class=\"c-no\">423</span><span class=\"c-src\">                agent.state.context.append(</span></div>\n<div class=\"c-line\" data-line=\"424\"><span class=\"c-no\">424</span><span class=\"c-src\">                    <span class=\"c-kw\">self</span>._build_memory_message(memories),</span></div>\n<div class=\"c-line\" data-line=\"425\"><span class=\"c-no\">425</span><span class=\"c-src\">                )</span></div>\n<div class=\"c-line\" data-line=\"426\"><span class=\"c-no\">426</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"427\"><span class=\"c-no\">427</span><span class=\"c-src\">        <span class=\"c-kw\">async</span> <span class=\"c-kw\">for</span> event <span class=\"c-kw\">in</span> next_handler(**input_kwargs):</span></div>\n<div class=\"c-line\" data-line=\"428\"><span class=\"c-no\">428</span><span class=\"c-src\">            <span class=\"c-kw\">yield</span> event</span></div>\n<div class=\"c-line\" data-line=\"429\"><span class=\"c-no\">429</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"430\"><span class=\"c-no\">430</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"431\"><span class=\"c-no\">431</span><span class=\"c-src\">    <span class=\"c-com\"># Hook: on_system_prompt (advertise the search tool to the LLM)</span></span></div>\n<div class=\"c-line\" data-line=\"432\"><span class=\"c-no\">432</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"433\"><span class=\"c-no\">433</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> on_system_prompt(</span></div>\n<div class=\"c-line\" data-line=\"434\"><span class=\"c-no\">434</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"435\"><span class=\"c-no\">435</span><span class=\"c-src\">        agent: <span class=\"c-str\">&quot;Agent&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"436\"><span class=\"c-no\">436</span><span class=\"c-src\">        current_prompt: str,</span></div>\n<div class=\"c-line\" data-line=\"437\"><span class=\"c-no\">437</span><span class=\"c-src\">    ) -&gt; str:</span></div>\n<div class=\"c-line\" data-line=\"438\"><span class=\"c-no\">438</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Append search-tool instructions to the system prompt.</span></div>\n<div class=\"c-line\" data-line=\"439\"><span class=\"c-no\">439</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"440\"><span class=\"c-no\">440</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"441\"><span class=\"c-no\">441</span><span class=\"c-src\">            agent (`Agent`):</span></div>\n<div class=\"c-line\" data-line=\"442\"><span class=\"c-no\">442</span><span class=\"c-src\">                The agent whose system prompt <span class=\"c-kw\">is</span> being transformed.</span></div>\n<div class=\"c-line\" data-line=\"443\"><span class=\"c-no\">443</span><span class=\"c-src\">            current_prompt (`str`):</span></div>\n<div class=\"c-line\" data-line=\"444\"><span class=\"c-no\">444</span><span class=\"c-src\">                The system prompt produced by previous middleware.</span></div>\n<div class=\"c-line\" data-line=\"445\"><span class=\"c-no\">445</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"446\"><span class=\"c-no\">446</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"447\"><span class=\"c-no\">447</span><span class=\"c-src\">            `str`:</span></div>\n<div class=\"c-line\" data-line=\"448\"><span class=\"c-no\">448</span><span class=\"c-src\">                The unchanged prompt <span class=\"c-kw\">in</span> static-control mode, otherwise the</span></div>\n<div class=\"c-line\" data-line=\"449\"><span class=\"c-no\">449</span><span class=\"c-src\">                prompt <span class=\"c-kw\">with</span> the ``memory_search`` nudge appended.</span></div>\n<div class=\"c-line\" data-line=\"450\"><span class=\"c-no\">450</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"451\"><span class=\"c-no\">451</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">self</span>._parameters.mode == <span class=\"c-str\">&quot;static_control&quot;</span>:</span></div>\n<div class=\"c-line\" data-line=\"452\"><span class=\"c-no\">452</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> current_prompt</span></div>\n<div class=\"c-line\" data-line=\"453\"><span class=\"c-no\">453</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> f<span class=\"c-str\">&quot;{current_prompt}\\n\\n{_TOOL_INSTRUCTIONS}&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"454\"><span class=\"c-no\">454</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"455\"><span class=\"c-no\">455</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> list_tools(<span class=\"c-kw\">self</span>) -&gt; list[<span class=\"c-str\">&quot;ToolBase&quot;</span>]:</span></div>\n<div class=\"c-line\" data-line=\"456\"><span class=\"c-no\">456</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;List memory tools provided by this middleware.</span></div>\n<div class=\"c-line\" data-line=\"457\"><span class=\"c-no\">457</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"458\"><span class=\"c-no\">458</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"459\"><span class=\"c-no\">459</span><span class=\"c-src\">            `list[ToolBase]`:</span></div>\n<div class=\"c-line\" data-line=\"460\"><span class=\"c-no\">460</span><span class=\"c-src\">                The ``memory_search`` tool <span class=\"c-kw\">in</span> agent-control modes</span></div>\n<div class=\"c-line\" data-line=\"461\"><span class=\"c-no\">461</span><span class=\"c-src\">                (``<span class=\"c-str\">&quot;agent_control&quot;</span>`` / ``<span class=\"c-str\">&quot;both&quot;</span>``), otherwise an empty</span></div>\n<div class=\"c-line\" data-line=\"462\"><span class=\"c-no\">462</span><span class=\"c-src\">                list. There <span class=\"c-kw\">is</span> no add tool — writing <span class=\"c-kw\">is</span> automatic.</span></div>\n<div class=\"c-line\" data-line=\"463\"><span class=\"c-no\">463</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"464\"><span class=\"c-no\">464</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">self</span>._parameters.mode == <span class=\"c-str\">&quot;static_control&quot;</span>:</span></div>\n<div class=\"c-line\" data-line=\"465\"><span class=\"c-no\">465</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> []</span></div>\n<div class=\"c-line\" data-line=\"466\"><span class=\"c-no\">466</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> _build_memory_tools(<span class=\"c-kw\">self</span>)</span></div>\n<div class=\"c-line\" data-line=\"467\"><span class=\"c-no\">467</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"468\"><span class=\"c-no\">468</span><span class=\"c-src\">    <span class=\"c-com\"># ==================================================================</span></span></div>\n<div class=\"c-line\" data-line=\"469\"><span class=\"c-no\">469</span><span class=\"c-src\">    <span class=\"c-com\"># ReMe job helpers (shared by hooks and tools)</span></span></div>\n<div class=\"c-line\" data-line=\"470\"><span class=\"c-no\">470</span><span class=\"c-src\">    <span class=\"c-com\"># ==================================================================</span></span></div>\n<div class=\"c-line\" data-line=\"471\"><span class=\"c-no\">471</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> _run_job(<span class=\"c-kw\">self</span>, name: str, **kwargs: Any) -&gt; Any:</span></div>\n<div class=\"c-line\" data-line=\"472\"><span class=\"c-no\">472</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Start the embedded app (<span class=\"c-kw\">if</span> needed) <span class=\"c-kw\">and</span> run a ReMe job.</span></div>\n<div class=\"c-line\" data-line=\"473\"><span class=\"c-no\">473</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"474\"><span class=\"c-no\">474</span><span class=\"c-src\">        Raises:</span></div>\n<div class=\"c-line\" data-line=\"475\"><span class=\"c-no\">475</span><span class=\"c-src\">            RuntimeError:</span></div>\n<div class=\"c-line\" data-line=\"476\"><span class=\"c-no\">476</span><span class=\"c-src\">                If ReMe reports ``success=<span class=\"c-kw\">False</span>``.</span></div>\n<div class=\"c-line\" data-line=\"477\"><span class=\"c-no\">477</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"478\"><span class=\"c-no\">478</span><span class=\"c-src\">        <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._ensure_started()</span></div>\n<div class=\"c-line\" data-line=\"479\"><span class=\"c-no\">479</span><span class=\"c-src\">        <span class=\"c-kw\">assert</span> <span class=\"c-kw\">self</span>._app <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"480\"><span class=\"c-no\">480</span><span class=\"c-src\">        response = <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._app.run_job(name, **kwargs)</span></div>\n<div class=\"c-line\" data-line=\"481\"><span class=\"c-no\">481</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> getattr(response, <span class=\"c-str\">&quot;success&quot;</span>, <span class=\"c-kw\">True</span>) <span class=\"c-kw\">is</span> <span class=\"c-kw\">False</span>:</span></div>\n<div class=\"c-line\" data-line=\"482\"><span class=\"c-no\">482</span><span class=\"c-src\">            <span class=\"c-kw\">raise</span> RuntimeError(</span></div>\n<div class=\"c-line\" data-line=\"483\"><span class=\"c-no\">483</span><span class=\"c-src\">                f<span class=\"c-str\">&quot;ReMe {name!r} failed: {getattr(response, &#x27;answer&#x27;, &#x27;&#x27;)}&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"484\"><span class=\"c-no\">484</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"485\"><span class=\"c-no\">485</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> response</span></div>\n<div class=\"c-line\" data-line=\"486\"><span class=\"c-no\">486</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"487\"><span class=\"c-no\">487</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> _search(</span></div>\n<div class=\"c-line\" data-line=\"488\"><span class=\"c-no\">488</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"489\"><span class=\"c-no\">489</span><span class=\"c-src\">        query: str,</span></div>\n<div class=\"c-line\" data-line=\"490\"><span class=\"c-no\">490</span><span class=\"c-src\">        *,</span></div>\n<div class=\"c-line\" data-line=\"491\"><span class=\"c-no\">491</span><span class=\"c-src\">        limit: int | <span class=\"c-kw\">None</span> = <span class=\"c-kw\">None</span>,</span></div>\n<div class=\"c-line\" data-line=\"492\"><span class=\"c-no\">492</span><span class=\"c-src\">    ) -&gt; list[str]:</span></div>\n<div class=\"c-line\" data-line=\"493\"><span class=\"c-no\">493</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;Search ReMe and return the retrieved memory texts.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"494\"><span class=\"c-no\">494</span><span class=\"c-src\">        response = <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._run_job(</span></div>\n<div class=\"c-line\" data-line=\"495\"><span class=\"c-no\">495</span><span class=\"c-src\">            _SEARCH_JOB,</span></div>\n<div class=\"c-line\" data-line=\"496\"><span class=\"c-no\">496</span><span class=\"c-src\">            query=query,</span></div>\n<div class=\"c-line\" data-line=\"497\"><span class=\"c-no\">497</span><span class=\"c-src\">            limit=<span class=\"c-kw\">self</span>._parameters.top_k <span class=\"c-kw\">if</span> limit <span class=\"c-kw\">is</span> <span class=\"c-kw\">None</span> <span class=\"c-kw\">else</span> limit,</span></div>\n<div class=\"c-line\" data-line=\"498\"><span class=\"c-no\">498</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"499\"><span class=\"c-no\">499</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> _extract_memory_texts(getattr(response, <span class=\"c-str\">&quot;metadata&quot;</span>, {}))</span></div>\n<div class=\"c-line\" data-line=\"500\"><span class=\"c-no\">500</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"501\"><span class=\"c-no\">501</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> _write_back(</span></div>\n<div class=\"c-line\" data-line=\"502\"><span class=\"c-no\">502</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"503\"><span class=\"c-no\">503</span><span class=\"c-src\">        messages: list[Msg],</span></div>\n<div class=\"c-line\" data-line=\"504\"><span class=\"c-no\">504</span><span class=\"c-src\">        session_id: str | <span class=\"c-kw\">None</span>,</span></div>\n<div class=\"c-line\" data-line=\"505\"><span class=\"c-no\">505</span><span class=\"c-src\">    ) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"506\"><span class=\"c-no\">506</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Persist a completed conversation increment to ReMe.</span></div>\n<div class=\"c-line\" data-line=\"507\"><span class=\"c-no\">507</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"508\"><span class=\"c-no\">508</span><span class=\"c-src\">        ``messages`` <span class=\"c-kw\">is</span> the full slice this turn appended to the agent&<span class=\"c-com\">#x27;s</span></span></div>\n<div class=\"c-line\" data-line=\"509\"><span class=\"c-no\">509</span><span class=\"c-src\">        context — the user input, every assistant step, <span class=\"c-kw\">and</span> every tool</span></div>\n<div class=\"c-line\" data-line=\"510\"><span class=\"c-no\">510</span><span class=\"c-src\">        call / tool result — so ReMe&<span class=\"c-com\">#x27;s ``auto_memory`` extraction sees the</span></span></div>\n<div class=\"c-line\" data-line=\"511\"><span class=\"c-no\">511</span><span class=\"c-src\">        whole exchange, <span class=\"c-kw\">not</span> just the final answer.</span></div>\n<div class=\"c-line\" data-line=\"512\"><span class=\"c-no\">512</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"513\"><span class=\"c-no\">513</span><span class=\"c-src\">        ``session_id`` <span class=\"c-kw\">is</span> passed <span class=\"c-kw\">in</span> per call (read live <span class=\"c-kw\">from</span> the agent),</span></div>\n<div class=\"c-line\" data-line=\"514\"><span class=\"c-no\">514</span><span class=\"c-src\">        never stored, so a shared middleware keeps conversations isolated.</span></div>\n<div class=\"c-line\" data-line=\"515\"><span class=\"c-no\">515</span><span class=\"c-src\">        Skipped (<span class=\"c-kw\">with</span> a warning) when no ``session_id`` <span class=\"c-kw\">is</span> available;</span></div>\n<div class=\"c-line\" data-line=\"516\"><span class=\"c-no\">516</span><span class=\"c-src\">        failures are logged rather than propagated so a write never blocks</span></div>\n<div class=\"c-line\" data-line=\"517\"><span class=\"c-no\">517</span><span class=\"c-src\">        the reply.</span></div>\n<div class=\"c-line\" data-line=\"518\"><span class=\"c-no\">518</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"519\"><span class=\"c-no\">519</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> session_id:</span></div>\n<div class=\"c-line\" data-line=\"520\"><span class=\"c-no\">520</span><span class=\"c-src\">            logger.warning(</span></div>\n<div class=\"c-line\" data-line=\"521\"><span class=\"c-no\">521</span><span class=\"c-src\">                <span class=\"c-str\">&quot;ReMe write skipped: no session_id captured from the agent.&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"522\"><span class=\"c-no\">522</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"523\"><span class=\"c-no\">523</span><span class=\"c-src\">            <span class=\"c-kw\">return</span></span></div>\n<div class=\"c-line\" data-line=\"524\"><span class=\"c-no\">524</span><span class=\"c-src\">        <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"525\"><span class=\"c-no\">525</span><span class=\"c-src\">            <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._run_job(</span></div>\n<div class=\"c-line\" data-line=\"526\"><span class=\"c-no\">526</span><span class=\"c-src\">                _AUTO_MEMORY_JOB,</span></div>\n<div class=\"c-line\" data-line=\"527\"><span class=\"c-no\">527</span><span class=\"c-src\">                messages=[m.model_dump(mode=<span class=\"c-str\">&quot;json&quot;</span>) <span class=\"c-kw\">for</span> m <span class=\"c-kw\">in</span> messages],</span></div>\n<div class=\"c-line\" data-line=\"528\"><span class=\"c-no\">528</span><span class=\"c-src\">                session_id=session_id,</span></div>\n<div class=\"c-line\" data-line=\"529\"><span class=\"c-no\">529</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"530\"><span class=\"c-no\">530</span><span class=\"c-src\">        <span class=\"c-kw\">except</span> Exception <span class=\"c-kw\">as</span> e:  <span class=\"c-com\"># noqa: BLE001</span></span></div>\n<div class=\"c-line\" data-line=\"531\"><span class=\"c-no\">531</span><span class=\"c-src\">            logger.warning(</span></div>\n<div class=\"c-line\" data-line=\"532\"><span class=\"c-no\">532</span><span class=\"c-src\">                <span class=\"c-str\">&quot;ReMe auto_memory failed for session_id=%s: %s&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"533\"><span class=\"c-no\">533</span><span class=\"c-src\">                session_id,</span></div>\n<div class=\"c-line\" data-line=\"534\"><span class=\"c-no\">534</span><span class=\"c-src\">                e,</span></div>\n<div class=\"c-line\" data-line=\"535\"><span class=\"c-no\">535</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"536\"><span class=\"c-no\">536</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"537\"><span class=\"c-no\">537</span><span class=\"c-src\">    <span class=\"c-com\"># ==================================================================</span></span></div>\n<div class=\"c-line\" data-line=\"538\"><span class=\"c-no\">538</span><span class=\"c-src\">    <span class=\"c-com\"># Helpers</span></span></div>\n<div class=\"c-line\" data-line=\"539\"><span class=\"c-no\">539</span><span class=\"c-src\">    <span class=\"c-com\"># ==================================================================</span></span></div>\n<div class=\"c-line\" data-line=\"540\"><span class=\"c-no\">540</span><span class=\"c-src\">    @staticmethod</span></div>\n<div class=\"c-line\" data-line=\"541\"><span class=\"c-no\">541</span><span class=\"c-src\">    <span class=\"c-kw\">def</span> _build_memory_message(memories: list[str]) -&gt; Msg:</span></div>\n<div class=\"c-line\" data-line=\"542\"><span class=\"c-no\">542</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Format retrieved ``memories`` <span class=\"c-kw\">as</span> a synthetic hint message.</span></div>\n<div class=\"c-line\" data-line=\"543\"><span class=\"c-no\">543</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"544\"><span class=\"c-no\">544</span><span class=\"c-src\">        The context entry uses an assistant-role ``Msg`` container because</span></div>\n<div class=\"c-line\" data-line=\"545\"><span class=\"c-no\">545</span><span class=\"c-src\">        user messages cannot carry ``HintBlock`` content. Formatters convert</span></div>\n<div class=\"c-line\" data-line=\"546\"><span class=\"c-no\">546</span><span class=\"c-src\">        the ``HintBlock`` itself into a user message before the model call.</span></div>\n<div class=\"c-line\" data-line=\"547\"><span class=\"c-no\">547</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"548\"><span class=\"c-no\">548</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"549\"><span class=\"c-no\">549</span><span class=\"c-src\">            memories (`list[str]`):</span></div>\n<div class=\"c-line\" data-line=\"550\"><span class=\"c-no\">550</span><span class=\"c-src\">                Retrieved memory texts to expose to the model.</span></div>\n<div class=\"c-line\" data-line=\"551\"><span class=\"c-no\">551</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"552\"><span class=\"c-no\">552</span><span class=\"c-src\">            `Msg`:</span></div>\n<div class=\"c-line\" data-line=\"553\"><span class=\"c-no\">553</span><span class=\"c-src\">                An assistant-role message containing one ``HintBlock``.</span></div>\n<div class=\"c-line\" data-line=\"554\"><span class=\"c-no\">554</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"555\"><span class=\"c-no\">555</span><span class=\"c-src\">        bullets = <span class=\"c-str\">&quot;\\n&quot;</span>.join(f<span class=\"c-str\">&quot;- {m}&quot;</span> <span class=\"c-kw\">for</span> m <span class=\"c-kw\">in</span> memories)</span></div>\n<div class=\"c-line\" data-line=\"556\"><span class=\"c-no\">556</span><span class=\"c-src\">        content = (</span></div>\n<div class=\"c-line\" data-line=\"557\"><span class=\"c-no\">557</span><span class=\"c-src\">            f<span class=\"c-str\">&quot;{_MEMORY_SECTION_HEADER}\\n&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"558\"><span class=\"c-no\">558</span><span class=\"c-src\">            f<span class=\"c-str\">&quot;{_MEMORY_SECTION_INTRO}\\n&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"559\"><span class=\"c-no\">559</span><span class=\"c-src\">            f<span class=\"c-str\">&quot;{bullets}&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"560\"><span class=\"c-no\">560</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"561\"><span class=\"c-no\">561</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> AssistantMsg(</span></div>\n<div class=\"c-line\" data-line=\"562\"><span class=\"c-no\">562</span><span class=\"c-src\">            name=_MEMORY_MSG_NAME,</span></div>\n<div class=\"c-line\" data-line=\"563\"><span class=\"c-no\">563</span><span class=\"c-src\">            content=[HintBlock(hint=content)],</span></div>\n<div class=\"c-line\" data-line=\"564\"><span class=\"c-no\">564</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"565\"><span class=\"c-no\">565</span><span class=\"c-src\">&nbsp;</span></div>\n</div>", "lines": 565, "explanation": "_middleware.py 来自 agentscope/QwenPaw 框架源码。结合左侧源码与右侧知识点理解此处设计意图；点「反向链接」可回到引用它的教程章节。", "knowledge_points": [], "related_docs": ["W07-中间件记忆与上下文治理"]};
